    buildModuleTopics() {
        const details = this.getModuleHelpDetails();
        const config = (typeof MODULE_PERMISSIONS_CONFIG !== 'undefined' && Array.isArray(MODULE_PERMISSIONS_CONFIG))
            ? MODULE_PERMISSIONS_CONFIG
            : [];
        const topics = [];
        const seen = new Set();

        config.forEach(mod => {
            if (seen.has(mod.key)) return;
            seen.add(mod.key);
            const d = details[mod.key] || {};
            const modLabel = this.getModuleLabel_(mod.key, mod.label);
            topics.push({
                id: 'mod-' + mod.key,
                categoryId: 'modules',
                moduleId: mod.key,
                title: modLabel,
                icon: mod.icon || 'fa-cube',
                summary: d.purpose || this.ui('modSummaryFallback', modLabel),
                purpose: d.purpose || this.ui('modPurposeFallback', modLabel),
                accessPath: d.accessPath || [],
                features: d.features || this.ui('modDefaultFeatures').slice(),
                workflow: d.workflow || this.ui('modDefaultWorkflow').slice(),
                commonTasks: d.commonTasks || [],
                tips: d.tips || this.ui('modDefaultTips').slice(),
                permissionsNote: d.permissionsNote || (mod.adminOnly ? this.ui('modPermAdmin') : this.ui('modPermGrant')),
                keywords: [modLabel, mod.key, (d.accessPath || []).join(' ')].join(' ')
            });
        });

        ['profile', 'reports', 'apptester', 'help'].forEach(key => {
            if (seen.has(key)) return;
            seen.add(key);
            const labels = { profile: 'ملفي الشخصي', reports: 'التقارير', apptester: 'اختبار التطبيق', help: 'المساعدة ومركز الدعم' };
            const icons = { profile: 'fa-user', reports: 'fa-file-lines', apptester: 'fa-vial', help: 'fa-circle-question' };
            const d = details[key] || {};
            const title = this.getModuleLabel_(key, labels[key]);
            topics.push({
                id: 'mod-' + key,
                categoryId: 'modules',
                moduleId: key,
                title,
                icon: icons[key],
                summary: d.purpose || '',
                purpose: d.purpose || '',
                accessPath: d.accessPath || [],
                features: d.features || [],
                workflow: d.workflow || [],
                commonTasks: d.commonTasks || [],
                tips: d.tips || [],
                permissionsNote: d.permissionsNote || '',
                keywords: title + ' ' + key
            });
        });

        return topics;
    },

    getAllTopics() {
        this._allTopicsCache = [
            ...this.getStaticTopics(),
            ...this.getPolicyTopics(),
            ...this.buildFaqTopics(),
            ...this.buildModuleTopics()
        ];
        return this._allTopicsCache;
    },

    getAppVersion() {
        try {
            if (typeof window !== 'undefined' && window.appVersion) return String(window.appVersion);
            if (typeof AppState !== 'undefined' && AppState.appVersion) return String(AppState.appVersion);
        } catch (_e) {}
        return '—';
    },

    normalizeSearch(s) {
        return String(s || '').toLowerCase().trim();
    },

    topicMatchesSearch(topic, q) {
        if (!q) return true;
        const blob = [
            topic.title, topic.summary, topic.purpose, topic.answer || '',
            (topic.accessPath || []).join(' '),
            (topic.features || []).join(' '),
            (topic.workflow || []).join(' '),
            (topic.tips || []).join(' '),
            (topic.commonTasks || []).map(t => [t.task, ...(t.steps || [])].join(' ')).join(' '),
            topic.keywords || ''
        ].join(' ').toLowerCase();
        return blob.includes(q);
    },

    getFilteredTopics() {
        const q = this.normalizeSearch(this.state.searchQuery);
        const cat = this.state.activeCategory;
        return this.getAllTopics().filter(t => {
            if (cat !== 'all' && t.categoryId !== cat) return false;
            return this.topicMatchesSearch(t, q);
        });
    },

    canOpenModule(moduleId) {
        if (!moduleId || moduleId === 'help') return false;
        if (typeof Permissions !== 'undefined' && typeof Permissions.hasAccess === 'function') {
            return Permissions.hasAccess(moduleId);
        }
        return false;
    },

